	}
}

static inline uint32_t i2c_ll_get_write_empty_fifo_num(i2c_hw_t *hw, i2c_id_t id)
{
	if (id == I2C_ID_0) {
		switch (hw->i2c0_hw->sm_bus_status.int_mode) {
		case 0x00:
			return 16;
		case 0x01:
			return 12;
		case 0x02:
			return 8;
		case 0x03:
			return 4;
		default:
			return 0;
		}
	} else {
		switch (hw->i2c1_hw->sm_bus_status.int_mode) {
		case 0x00:
